using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.Animations;
using System.IO;
using System.Linq;
public static class CoastPolish {
 const string D="Assets/Lighthouse_Authored";
 static GameObject Place(string filename,Vector3 at,float height,float yaw){var path=AssetDatabase.FindAssets(Path.GetFileNameWithoutExtension(filename)+" t:Model",new[]{"Assets/Art/External"}).Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileName(p)==filename);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.transform.rotation=Quaternion.Euler(0,yaw,0);var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.localScale*=height/b.size.y;b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);var hits=Physics.RaycastAll(new Vector3(at.x,50,at.z),Vector3.down,55).Where(h=>h.collider.name.Contains("meadow")||h.collider.name.StartsWith("Cliff")||h.collider.name.StartsWith("Beach sand")).OrderByDescending(h=>h.point.y).ToArray();if(hits.Length>0)at.y=hits[0].point.y;g.transform.position+=at-new Vector3(b.center.x,b.min.y,b.center.z);return g;}
 public static void Apply(){EditorSceneManager.OpenScene(CoastAuthored.Scene);var old=GameObject.Find("Polished plant clusters");if(old)Object.DestroyImmediate(old);var plants=new GameObject("Polished plant clusters");var points=new[]{new Vector3(-14,3.6f,-2),new Vector3(16,3.6f,6),new Vector3(-12,7.6f,16),new Vector3(11,7.6f,18),new Vector3(-7,12.4f,24),new Vector3(8,12.4f,25),new Vector3(-16,.32f,-10),new Vector3(13,.32f,-8),new Vector3(-15,3.6f,3),new Vector3(-17,3.6f,5),new Vector3(-10,7.6f,18),new Vector3(-6,7.6f,17),new Vector3(2,7.6f,10),new Vector3(13,7.6f,15),new Vector3(-5,12.4f,28),new Vector3(3,12.4f,29)};for(int i=0;i<points.Length;i++){Place("Bush_Common_Flowers.fbx",points[i],1.1f+i%2*.25f,i*43).transform.SetParent(plants.transform);Place("Grass_Common_Short.fbx",points[i]+new Vector3(.75f,0,-.6f),.5f,i*53).transform.SetParent(plants.transform);Place("Grass_Wispy_Short.fbx",points[i]+new Vector3(-.65f,0,-.7f),.6f,i*67).transform.SetParent(plants.transform);}
 var sky=new Material(Shader.Find("Coast/DaySky"));var stored=AssetDatabase.LoadAssetAtPath<Material>(D+"/Painted daylight.mat");if(!stored){AssetDatabase.CreateAsset(sky,D+"/Painted daylight.mat");stored=sky;}stored.shader=Shader.Find("Coast/DaySky");RenderSettings.skybox=stored;var skyCamera=Camera.main.GetComponent<Skybox>();if(!skyCamera)skyCamera=Camera.main.gameObject.AddComponent<Skybox>();skyCamera.material=stored;RenderSettings.fogColor=new Color(.52f,.78f,.88f);
 var podium=AssetDatabase.LoadAssetAtPath<Material>(D+"/Lighthouse dressed stone podium.mat");if(podium){podium.shader=Shader.Find("Coast/Painted");podium.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(D+"/PaintedSurfaceAtlas.png"));podium.SetFloat("_Kind",3);podium.SetFloat("_Scale",4);podium.color=new Color(.85f,.89f,.90f);}
 foreach(var f in Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None)){if(f.name.Contains("grass fringe")||f.name.Contains("Flower")||f.name.Contains("petal")||f.name.Contains("Trailing")||f.name.Contains("heart")||f.name.Contains("leaf")){var col=f.GetComponent<Collider>();if(col)Object.DestroyImmediate(col);}}
 var player=GameObject.Find("Explorer");foreach(var r in player.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int mi=0;mi<mats.Length;mi++){if(!mats[mi])continue;string mp=D+"/Explorer_"+r.name+"_"+mi+".mat";var clean=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!clean){clean=new Material(mats[mi]);AssetDatabase.CreateAsset(clean,mp);}clean.DisableKeyword("_NORMALMAP");clean.SetTexture("_BumpMap",null);clean.SetFloat("_BumpScale",0);mats[mi]=clean;}r.sharedMaterials=mats;}var animator=player.GetComponentInChildren<Animator>();if(animator){string cp=D+"/ExplorerLocomotion.controller";AssetDatabase.DeleteAsset(cp);var controller=AnimatorController.CreateAnimatorControllerAtPath(cp);controller.AddParameter("Speed",AnimatorControllerParameterType.Float);var animpath=AssetDatabase.FindAssets("UAL1_Standard t:Model").Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileName(p)=="UAL1_Standard.fbx");var clips=AssetDatabase.LoadAllAssetsAtPath(animpath).OfType<AnimationClip>().ToArray();var idle=clips.First(c=>c.name.Contains("|Idle_Loop"));var walk=clips.First(c=>c.name.Contains("|Walk_Loop"));var a=controller.AddMotion(idle);var b=controller.AddMotion(walk);controller.layers[0].stateMachine.defaultState=a;var ab=a.AddTransition(b);ab.hasExitTime=false;ab.duration=.15f;ab.AddCondition(AnimatorConditionMode.Greater,.1f,"Speed");var ba=b.AddTransition(a);ba.hasExitTime=false;ba.duration=.15f;ba.AddCondition(AnimatorConditionMode.Less,.1f,"Speed");animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;}
 Directory.CreateDirectory(D+"/Prefabs");var all=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None);int index=0;foreach(var r in all.Where(r=>r.name.StartsWith("Cliff")&&!r.name.Contains("grass"))){var group=new GameObject("Cliff module "+index);var p=new Vector3(r.bounds.center.x,r.bounds.min.y,r.bounds.center.z);group.transform.position=p;r.transform.SetParent(group.transform,true);var crown=all.FirstOrDefault(q=>q.name==r.name+" mossy grass crown");if(crown)crown.transform.SetParent(group.transform,true);var fringe=all.FirstOrDefault(q=>q.name==r.name+" grass fringe");if(fringe)fringe.transform.SetParent(group.transform,true);group.transform.position=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(group,D+"/Prefabs/Cliff_"+index+".prefab");group.transform.position=p;index++;}
 EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("COAST_POLISH_COMPLETE modules="+index);}
}
